+func isFilesystemMetadataInspection(call *ast.CallExpr) bool {
+	selector, ok := call.Fun.(*ast.SelectorExpr)
+	if !ok {
+		return false
+	}
+	switch selector.Sel.Name {
+	case "Lstat", "Open", "OpenFile", "ReadDir", "ReadFile", "Readlink", "Stat":
+		return true
