   114		}
   115		if !info.Mode().IsRegular() {
   116			return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
   117		}
   118	
   119		content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
   120		if err != nil {
   121			return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
   122		}
   123		pointer := strings.TrimRight(string(content), "\r\n")
   124		if pointer == "" {
   125			return "", fmt.Errorf("parse commondir file at %s: empty value", commonFile)
   126		}
   127	
   128		resolved, err := resolveMetadataDirectory("common Git directory", gitDirPath, pointer)
   129		if err != nil {
   130			return "", err
   131		}
   132		return resolved, nil
   133	}
   134	
   135	func resolveWorktreeID(gitDirPath, commonDir string) (string, error) {
   136		same, err := metadataDirectoriesIdentifySameFile(gitDirPath, commonDir)
   137		if err != nil {
   138			return "", fmt.Errorf("compare Git and common directories: %w", err)
   139		}
   140		if same {
   141			return "", nil
   142		}
   143	
   144		registrationRoot := filepath.Join(commonDir, "worktrees")
   145		registrationPath, err := filepath.EvalSymlinks(gitDirPath)
   146		if err != nil {
   147			return "", fmt.Errorf("resolve linked-worktree registration %s: %w", gitDirPath, err)
   148		}
   149		same, err = metadataDirectoriesIdentifySameFile(filepath.Dir(registrationPath), registrationRoot)
   150		if err != nil {
   151			return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
   152		}
   153		if !same {
   154			return "", fmt.Errorf("git directory %s is not an immediate child of %s", gitDirPath, registrationRoot)
   155		}
   156	
   157		id := filepath.Base(registrationPath)
   158		if id == "." || id == string(filepath.Separator) || id == "" {
   159			return "", fmt.Errorf("git directory %s has no worktree registration name", gitDirPath)
   160		}
   161		return id, nil
   162	}
   163	
   164	// Preserve the pointer spelling until validation so a missing component cannot
   165	// disappear through lexical cleaning before the filesystem sees it.
   166	func resolveMetadataPath(base, value string) string {
   167		if filepath.IsAbs(value) {
   168			return value
   169		}
   170		return base + string(filepath.Separator) + value
   171	}
   172	
   173	func resolveMetadataDirectory(label, base, value string) (string, error) {
   174		resolved := resolveMetadataPath(base, value)
   175		if err := requireMetadataDirectory(label, resolved); err != nil {
   176			return "", err
   177		}
   178	
   179		cleaned := filepath.Clean(resolved)
   180		if cleaned == resolved {
   181			return cleaned, nil
   182		}
   183		// Cleaning a path through a symlink before resolving ".." can change which
   184		// directory it names, so keep the lexical result only when identity agrees.
   185		if same, err := metadataDirectoriesIdentifySameFile(resolved, cleaned); err == nil && same {
   186			return cleaned, nil
   187		}
   188	
   189		physical, err := filepath.EvalSymlinks(resolved)
   190		if err != nil {
   191			return "", fmt.Errorf("resolve %s at %s: %w", label, resolved, err)
   192		}
   193		return filepath.Clean(physical), nil
   194	}
   195	
   196	func requireMetadataDirectory(label, path string) error {
   197		info, err := os.Stat(path) //nolint:gosec // the explicit-root API resolves caller-selected repository metadata.
   198		if err != nil {
   199			return fmt.Errorf("inspect %s at %s: %w", label, path, err)
   200		}
   201		if !info.IsDir() {
   202			return fmt.Errorf("%s at %s is not a directory", label, path)
   203		}
   204		return nil
   205	}
   206	
   207	func metadataDirectoriesIdentifySameFile(a, b string) (bool, error) {
   208		aInfo, err := os.Stat(a) //nolint:gosec // explicit-root metadata paths are validated before identity comparison.
   209		if err != nil {
   210			return false, fmt.Errorf("inspect %s: %w", a, err)
   211		}
   212		if !aInfo.IsDir() {
   213			return false, fmt.Errorf("%s is not a directory", a)
   214		}
   215		bInfo, err := os.Stat(b)
   216		if err != nil {
   217			return false, fmt.Errorf("inspect %s: %w", b, err)
   218		}
   219		if !bInfo.IsDir() {
   220			return false, fmt.Errorf("%s is not a directory", b)
   221		}
   222		return os.SameFile(aInfo, bInfo), nil
   223	}

