286	func isFilesystemMetadataInspection(call *ast.CallExpr) bool {
287		selector, ok := call.Fun.(*ast.SelectorExpr)
288		if !ok {
289			return false
290		}
291		switch selector.Sel.Name {
292		case "DirFS", "Lstat", "Open", "OpenFile", "OpenInRoot", "OpenRoot", "ReadDir", "ReadFile", "Readlink", "Stat":
293			return true
294		default:
295			return false
296		}
