333	func packageStringValues(file *ast.File) map[string]string {
334		values := map[string]string{}
335		for _, decl := range file.Decls {
336			gen, ok := decl.(*ast.GenDecl)
337			if !ok {
338				continue
339			}
340			for _, spec := range gen.Specs {
341				valueSpec, ok := spec.(*ast.ValueSpec)
342				if !ok {
343					continue
344				}
345				for i, expr := range valueSpec.Values {
346					literal, ok := expr.(*ast.BasicLit)
347					if !ok || literal.Kind != token.STRING || i >= len(valueSpec.Names) {
348						continue
349					}
350					unquoted, err := strconv.Unquote(literal.Value)
351					if err == nil {
352						values[valueSpec.Names[i].Name] = unquoted
353					}
354				}
355			}
356		}
357		return values
358	}
