380	func isLegacyMetadataResolverCall(call *ast.CallExpr, importNames map[string]bool, dotImported, samePackage bool) bool {
381		legacyName := func(name string) bool {
382			return name == "ResolveDotGitPath" || name == "ResolveCommonGitPath"
383		}
384		if ident, ok := call.Fun.(*ast.Ident); ok {
385			return (dotImported || samePackage) && legacyName(ident.Name)
386		}
387		selector, ok := call.Fun.(*ast.SelectorExpr)
388		if !ok || !legacyName(selector.Sel.Name) {
389			return false
390		}
391		pkg, ok := selector.X.(*ast.Ident)
392		return ok && importNames[pkg.Name]
393	}
